const safeStorage=(()=>{try{const store=window.localStorage;return {getItem:(k)=>{try{return store.getItem(k)}catch(e){return null}},setItem:(k,v)=>{try{store.setItem(k,v);return true}catch(e){return false}},removeItem:(k)=>{try{store.removeItem(k);return true}catch(e){return false}}}}catch(e){return {getItem:()=>null,setItem:()=>false,removeItem:()=>false}}})();
let savedCart={}; try{savedCart=JSON.parse(safeStorage.getItem('pp-cart')||'{}')||{}}catch(e){savedCart={};}
function sanitizeCart(cart){const clean={};if(!cart||typeof cart!=='object'||Array.isArray(cart))return clean;for(const [id,qty] of Object.entries(cart)){if(!products.some(p=>p.id===id))continue;const n=Math.floor(Number(qty));if(Number.isFinite(n)&&n>0)clean[id]=Math.min(99,n)}return clean}
savedCart=sanitizeCart(savedCart);
const state={filter:'all',query:'',cart:savedCart,pricesLoaded:false,checkoutSession:null};
const money=n=>`৳${Number(n||0).toLocaleString('en-BD')}`;
function escapeHtml(value){return String(value??'').replace(/[&<>'"`=]/g, ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\'':'&#39;','"':'&quot;','`':'&#96;','=':'&#61;'}[ch]||ch));}
function cryptoSafeId(){if(window.crypto?.randomUUID)return window.crypto.randomUUID();if(window.crypto?.getRandomValues){const bytes=new Uint8Array(12);window.crypto.getRandomValues(bytes);return [...bytes].map(b=>b.toString(16).padStart(2,'0')).join('')}return `pp-${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function blobToDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(reader.error||new Error('Could not read audio'));reader.readAsDataURL(blob);});}
const el=s=>document.querySelector(s); const els=s=>[...document.querySelectorAll(s)];
async function api(path,options={}){ if(!API_BASE) throw new Error('API_NOT_CONFIGURED'); const r=await fetch(API_BASE+path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}}); const data=await r.json().catch(()=>({})); if(!r.ok) throw new Error(data.message||data.error||`HTTP_${r.status}`); return data; }
async function loadPrices(){try{const data=await api('/api/products'); if(Array.isArray(data.products)){data.products.forEach(remote=>{const p=products.find(x=>x.id===remote.id); if(p){p.price=Number(remote.price);p.old=Number(remote.old||0);p.stock=remote.stockLabel||p.stock;}}); state.pricesLoaded=true; renderProducts();renderCart();}}catch(e){/* static fallback keeps storefront usable */}}
function saveCart(){state.cart=sanitizeCart(state.cart);safeStorage.setItem('pp-cart',JSON.stringify(state.cart)); renderCartCount(); renderCart();}
function cartQty(){return Object.values(state.cart).reduce((a,b)=>a+Number(b||0),0)}
function cartLineCount(){return Object.keys(state.cart).length}
function renderCartCount(){const n=cartQty();el('#cartCount').textContent=n;el('#cartCount').setAttribute('aria-label',`${n} item${n===1?'':'s'} in cart`);const sub=el('#cartSubline');if(sub)sub.textContent=`${n} item${n===1?'':'s'} · ${cartLineCount()} product${cartLineCount()===1?'':'s'}`}
function filteredProducts(){const q=state.query.trim().toLowerCase(); return products.filter(p=>{const matchesFilter=state.filter==='small-pets'?['fish','rabbit','hamster','treats'].includes(p.category):p.tags.includes(state.filter); if(!matchesFilter)return false; if(!q)return true; const haystack=[p.name,p.brand,p.category,p.type,p.weight,p.desc,p.pet].join(' ').toLowerCase(); return haystack.includes(q);})}
function productVisual(p,large=false){return `<div class="${large?'product-detail-media':''} ${large?'':'product-media '+(p.category==='bird'?'bird':'')}"><div class="pack ${p.pack==='cream'?'cream':''}"><div><div class="mini-pet">${p.pet}</div><div class="mini-brand">Purrfect<br/>Pantry</div></div></div></div>`}
function renderProducts(){const grid=el('#productGrid'), empty=el('#emptyState'); const list=filteredProducts(); const countLabel=el('#catalogSearchHint'); if(countLabel){countLabel.textContent=state.query.trim()?`${list.length} matching listing${list.length===1?'':'s'} · Search covers food name, pet type, flavour, brand and pack size.`:`${products.length} product listings · Try “cat”, “chicken”, “1 kg” or a product name.`;} const clear=el('#catalogSearchClear'); if(clear)clear.hidden=!state.query.trim(); grid.innerHTML=list.map(p=>`<article class="product-card"><button class="product-media-wrap" data-view="${p.id}" aria-label="View ${p.name}" style="all:unset;cursor:pointer">${productVisual(p)}</button><div class="product-body"><div class="meta"><span>${p.brand}</span><span>·</span><span>${p.weight}</span></div><h3>${p.name}</h3><div class="meta"><span>${p.type}</span><span>·</span><span class="stock">${p.stock}</span></div><div class="price-row"><div><span class="price">${money(p.price)}</span>${p.old?`<span class="old">${money(p.old)}</span>`:''}</div></div><div class="card-actions"><button class="btn outline" data-view="${p.id}">Details</button><button class="btn btn-primary" data-add="${p.id}">Add to bag</button><button class="btn buy-now" data-buy="${p.id}">Buy now</button></div></div></article>`).join(''); empty.hidden=list.length>0; grid.hidden=list.length===0; els('[data-add]').forEach(b=>b.addEventListener('click',()=>addToCart(b.dataset.add))); els('[data-buy]').forEach(b=>b.addEventListener('click',()=>buyNow(b.dataset.buy))); els('[data-view]').forEach(b=>b.addEventListener('click',()=>openProduct(b.dataset.view)));}
function addToCart(id){const p=products.find(x=>x.id===id);if(!p)return;state.cart[id]=Math.max(0,Number(state.cart[id]||0)+1);saveCart();toast(`${p.name} added to cart`);}
function buyNow(id){addToCart(id);openCheckout();}
function removeFromCart(id){delete state.cart[id];saveCart()}
function changeQty(id,d){const next=Number(state.cart[id]||1)+d;if(next<=0)delete state.cart[id];else state.cart[id]=Math.min(99,next);saveCart()}
function renderCart(){const wrap=el('#cartItems');const entries=Object.entries(state.cart).filter(([id,q])=>products.some(p=>p.id===id)&&Number(q)>0);if(!entries.length){wrap.innerHTML='<div class="empty-state"><strong>Your cart is empty.</strong><br><span>Add products from the shelf to start an order.</span></div>';el('#cartSubtotal').textContent=money(0);renderCartCount();return}let total=0;wrap.innerHTML=entries.map(([id,q])=>{const p=products.find(x=>x.id===id);const qty=Math.max(1,Number(q)||1);total+=p.price*qty;return `<div class="cart-item"><div class="cart-thumb">${productVisual(p)}</div><div><h4>${p.name}</h4><p>${p.weight} · ${money(p.price)} each</p><div class="qty"><button data-minus="${id}" aria-label="Decrease ${p.name}">−</button><span aria-live="polite">${qty}</span><button data-plus="${id}" aria-label="Increase ${p.name}">+</button><button class="text-btn" data-remove="${id}">Remove</button></div></div><strong>${money(p.price*qty)}</strong></div>`}).join('');el('#cartSubtotal').textContent=money(total);renderCartCount();els('[data-minus]').forEach(b=>b.onclick=()=>changeQty(b.dataset.minus,-1));els('[data-plus]').forEach(b=>b.onclick=()=>changeQty(b.dataset.plus,1));els('[data-remove]').forEach(b=>b.onclick=()=>removeFromCart(b.dataset.remove));}
function openCart(){renderCart();el('#cartDrawer').classList.add('open');el('#cartDrawer').setAttribute('aria-hidden','false');el('#scrim').hidden=false;document.body.classList.add('cart-open')}
function closeCart(){el('#cartDrawer').classList.remove('open');el('#cartDrawer').setAttribute('aria-hidden','true');el('#scrim').hidden=true;document.body.classList.remove('cart-open')}
function openProduct(id){const p=products.find(x=>x.id===id);if(!p){toast('Product is no longer available');return}el('#productModalBody').innerHTML=`<div class="product-modal-grid">${productVisual(p,true)}<div class="product-detail-copy"><p class="eyebrow">${({cat:'Cat Food',dog:'Dog Food',bird:'Bird Food',fish:'Fish Food',rabbit:'Rabbit Food',hamster:'Hamster Food',treats:'Treats'}[p.category]||'Pet Food')} · ${p.weight}</p><h2>${p.name}</h2><p>${p.desc}</p><div class="price-row"><div><span class="price">${money(p.price)}</span>${p.old?`<span class="old">${money(p.old)}</span>`:''}</div><span class="stock">${p.stock}</span></div><div class="hero-ctas"><button class="btn btn-primary" id="modalAdd">Add to bag</button><button class="btn outline" id="modalBuy">Buy now</button></div></div></div>`;el('#modalAdd').onclick=()=>{addToCart(id);el('#productModal').close()};el('#modalBuy').onclick=()=>{el('#productModal').close();buyNow(id)};el('#productModal').showModal()}
function openCheckout(){if(!cartQty()){toast('Add at least one item first');return}renderCheckout();el('#checkoutModal').showModal()}
function renderCheckout(){state.cart=sanitizeCart(state.cart);let total=0;const lines=Object.entries(state.cart).map(([id,q])=>{const p=products.find(x=>x.id===id);if(!p)return '';const qty=Math.min(99,Math.max(1,Math.floor(Number(q)||1)));total+=p.price*qty;return `<div class="checkout-line"><span>${escapeHtml(p.name)} × ${qty}</span><strong>${money(p.price*qty)}</strong></div>`}).join('');el('#checkoutSummary').innerHTML=lines||'<p class="tiny-note">Your cart is empty.</p>';el('#checkoutTotal').textContent=money(total)}
function validBDPhone(v){return /^(?:\+8801|8801|01)\d{9}$/.test(v.replace(/[\s-]/g,''))}
function normalizeBDPhone(v){let s=v.replace(/[\s-]/g,''); if(s.startsWith('+880')) return s.slice(1); if(s.startsWith('880')) return s; return '880'+s.slice(1)}
function setOtpStage(show){const otp=el('#otpStage'),stage=el('#checkoutStage');if(!otp||!stage)return;otp.hidden=!show;stage.hidden=show;if(show&&el('#otpInput'))el('#otpInput').focus()}
async function sendOtp(){const form=el('#checkoutForm'); const phone=normalizeBDPhone(form.phone.value); if(!validBDPhone(form.phone.value)){toast('Enter a valid Bangladesh mobile number');return false} if(!API_BASE){toast('OTP server is not configured yet');return false} try{const data=await api('/api/otp/send',{method:'POST',body:JSON.stringify({phone})});state.checkoutSession={phone,otpToken:data.otpToken}; setOtpStage(true); toast('OTP sent to your mobile number'); return true}catch(e){toast(e.message||'Could not send OTP');return false}}
async function verifyOtp(){const code=el('#otpInput').value.trim(); if(!state.checkoutSession?.otpToken||!state.checkoutSession?.phone){toast('Please request a new OTP first');setOtpStage(false);return} if(!/^\d{6}$/.test(code)){toast('Enter the 6-digit OTP');return} try{const data=await api('/api/otp/verify',{method:'POST',body:JSON.stringify({otpToken:state.checkoutSession.otpToken,phone:state.checkoutSession.phone,code})}); if(data.verified){await placeVerifiedOrder(data.verificationToken);}}catch(e){toast(e.message||'OTP verification failed')}}
async function placeVerifiedOrder(verificationToken){const fd=new FormData(el('#checkoutForm')); const items=Object.entries(state.cart).map(([id,q])=>({id,qty:q})); try{const data=await api('/api/orders',{method:'POST',body:JSON.stringify({verificationToken,customer:{name:fd.get('name'),phone:normalizeBDPhone(fd.get('phone')),address:fd.get('address'),payment:fd.get('payment')},items})}); safeStorage.setItem('pp-last-order',JSON.stringify(data.order));state.cart={};saveCart();el('#checkoutModal').close();toast(`Order ${data.order.orderId} confirmed`);el('#checkoutForm').reset();el('#otpInput').value='';setOtpStage(false);}catch(e){toast(e.message||'Could not create order')}}
const REVIEW_KEY='pp-reviews';
const VOICE_KEY='pp-voicemail-draft';
const VOICE_OUTBOX_KEY='pp-voicemail-outbox';
