function renderReviews(){const list=el('#reviewList');if(!list)return;const items=loadReviews();const summary=el('#reviewSummary');if(summary)summary.textContent=items.length?`${items.length} customer comment${items.length===1?'':'s'} saved on this browser.`:'No customer comments yet.';if(!items.length){list.innerHTML='<div class="review-empty">No comments yet. Be the first customer to share a real experience.</div>';return}list.innerHTML=items.slice().reverse().map(r=>`<article class="review-card"><div class="review-card-head"><div><h4>${escapeHtml(r.name)}</h4><small>${escapeHtml(r.product||'Purrfect Pantry')} · ${escapeHtml(r.date)}</small></div><span class="review-stars" aria-label="${r.rating} out of 5 stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><p>${escapeHtml(r.comment)}</p></article>`).join('')}
async function syncReviewsFromApi(){if(!API_BASE)return;try{const data=await api('/api/reviews');if(Array.isArray(data.reviews)){mergeRemoteReviews(data.reviews);renderReviews()}}catch(e){/* local comments remain available */}}
async function initReviewModule(){renderReviews();syncReviewsFromApi();const form=el('#reviewForm');const comment=el('#reviewComment');const count=el('#reviewCharCount');if(comment&&count)comment.oninput=()=>count.textContent=`${comment.value.length} / 500`;if(form)form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form);const item={name:String(fd.get('name')||'').trim(),rating:Math.max(1,Math.min(5,Number(fd.get('rating')||5))),product:String(fd.get('product')||'').trim(),comment:String(fd.get('comment')||'').trim(),date:new Date().toLocaleDateString('en-BD',{year:'numeric',month:'short',day:'numeric'})};if(item.name.length<2||item.comment.length<3){toast('Please add your name and a comment');return}let posted=false;try{if(API_BASE){const data=await api('/api/reviews',{method:'POST',body:JSON.stringify({name:item.name,rating:item.rating,product:item.product,comment:item.comment})});if(data.review){item.id=data.review.id;item.date=data.review.date;posted=true}}}catch(e){}const items=loadReviews();items.push({...item,id:item.id||cryptoSafeId()});saveReviews(items);form.reset();if(count)count.textContent='0 / 500';renderReviews();toast(posted?'Your comment was posted':'Your comment was saved on this browser');};const clear=el('#clearMyReviews');if(clear)clear.onclick=()=>{saveReviews([]);renderReviews();toast('Your saved comments were cleared')};}
function setVoiceStatus(text,recording=false){const s=el('#voiceStatus'),d=el('#voiceDot');if(s)s.textContent=text;if(d)d.classList.toggle('recording',recording)}
