async function startVoiceRecording(){if(mediaRecorder&&mediaRecorder.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Voice recording is not supported by this browser');return}try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});mediaChunks=[];voiceBlob=null;mediaRecorder=new MediaRecorder(voiceStream);mediaRecorder.ondataavailable=e=>{if(e.data.size)mediaChunks.push(e.data)};mediaRecorder.onstop=()=>{voiceBlob=new Blob(mediaChunks,{type:mediaRecorder.mimeType||'audio/webm'});const url=URL.createObjectURL(voiceBlob);const a=el('#voicePlayback');if(a){if(a.dataset.objectUrl)URL.revokeObjectURL(a.dataset.objectUrl);a.dataset.objectUrl=url;a.src=url;a.hidden=false;a.load()}rememberVoiceDraftMeta();const del=el('#voiceDelete'),send=el('#voiceSend');if(del)del.disabled=false;if(send)send.disabled=false;setVoiceStatus('Voice message ready to send')};mediaRecorder.start();resetVoiceTimer();voiceTimerHandle=setInterval(tickVoiceTimer,1000);el('#voiceStart').disabled=true;el('#voiceStop').disabled=false;setVoiceStatus('Recording…',true);toast('Recording started')}catch(e){toast('Microphone permission was denied or unavailable')}}
