async function sendVoiceMessage(){if(!voiceBlob){toast('Record a voice message first');return}const name=String(el('#voiceName')?.value||'').trim();const phone=String(el('#voicePhone')?.value||'').trim();if(phone&&!validBDPhone(phone)){toast('Enter a valid Bangladesh phone number or leave it blank');return}try{const dataUrl=await blobToDataUrl(voiceBlob);if(String(dataUrl).length>1500000){toast('Voice message is too large. Keep it under 60 seconds.');return}if(API_BASE){const data=await api('/api/voicemails',{method:'POST',body:JSON.stringify({name,phone,mimeType:voiceBlob.type,data:dataUrl})});toast(data.message||'Voicemail sent to the shop')}else{const a=document.createElement('a');a.href=dataUrl;a.download=`purrfect-pantry-voicemail-${new Date().toISOString().replace(/[:.]/g,'-')}.webm`;a.click();addVoiceToLocalOutbox();toast('Voicemail saved on this device. Connect the shop API to deliver it to the team.')}rememberVoiceDraftMeta()}catch(e){toast(e.message||'Could not process the voicemail')}}
