function initVoicemail(){updateVoiceSendLabel();const s=el('#voiceStart'),st=el('#voiceStop'),send=el('#voiceSend'),d=el('#voiceDelete');if(s)s.onclick=startVoiceRecording;if(st)st.onclick=stopVoiceRecording;if(send)send.onclick=sendVoiceMessage;if(d)d.onclick=deleteVoiceDraft;els('[data-open-voicemail]').forEach(a=>a.onclick=e=>{e.preventDefault();el('#reviews')?.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>el('#voiceStart')?.focus(),350)});}

