function renderRescueList(){const list=el('#rescueList'),summary=el('#rescueSummary');if(!list)return;const items=loadLocalRescues().filter(r=>r.status!=='resolved');if(summary)summary.textContent=items.length?`${items.length} active rescue request${items.length===1?'':'s'} visible on this browser.`:'No active rescue requests yet.';if(!items.length){list.innerHTML='<div class="rescue-empty">No active markers yet. Be the first to report an animal that needs help.</div>';return}list.innerHTML=items.slice().reverse().map(r=>`<article class="rescue-card-item"><div class="rescue-card-icon ${escapeHtml(r.animal)}">${RESCUE_ICONS[r.animal]||'🐾'}</div><div class="rescue-card-body"><div class="rescue-card-head"><strong>${escapeHtml(String(r.animal||'Animal').toUpperCase())}</strong><span class="rescue-urgency ${escapeHtml(r.urgency)}">${escapeHtml(rescueStatusLabel(r.urgency))}</span></div><p>${escapeHtml(r.description)}</p><small>${escapeHtml(r.place||'Map location')} · ${escapeHtml(r.countryName||'')} · ${Number(r.lat).toFixed(5)}, ${Number(r.lng).toFixed(5)}</small>${r.hasMedia?`<span class="rescue-card-media">▣ ${escapeHtml(r.mediaType==='video'?'Video':'Photo')} attached</span>`:''}</div><button class="text-btn rescue-view-btn" type="button" data-rescue-id="${escapeHtml(r.id)}">View on map</button></article>`).join('');els('.rescue-view-btn').forEach(b=>b.onclick=()=>{const r=loadLocalRescues().find(x=>x.id===b.dataset.rescueId);if(!r)return;if(rescueMap){rescueMap.setView([r.lat,r.lng],Math.max(rescueMap.getZoom(),15));const m=rescueMarkers.get(r.id);if(m)m.openPopup()};el('#rescueMap')?.scrollIntoView({behavior:'smooth',block:'center'})})}
function clearRescueMarkers(){rescueMarkers.forEach(m=>{try{m.remove()}catch(e){}});rescueMarkers.clear()}
function markerColorClass(r){return r.urgency==='urgent'?'urgent':r.urgency==='high'?'high':r.animal}
function addRescueMarker(r){if(!rescueMap||!window.L)return;const cls=markerColorClass(r),icon=L.divIcon({className:'rescue-pin-wrap',html:`<div class="rescue-pin ${cls}">${RESCUE_ICONS[r.animal]||'🐾'}<span>${r.urgency==='urgent'?'!':''}</span></div>`,iconSize:[40,46],iconAnchor:[20,44],popupAnchor:[0,-42]});const m=L.marker([r.lat,r.lng],{icon,title:`${r.animal} rescue ${rescueStatusLabel(r.urgency)}`}).addTo(rescueMap);m.bindPopup(rescuePopup(r),{maxWidth:260});rescueMarkers.set(r.id,m)}
