async function updateRescueCountry(lat,lng){const status=el('#rescueCountryStatus'),badge=el('#rescueOperatorStatus');if(!API_BASE){if(status)status.textContent='Country routing will activate when the rescue API is connected.';if(badge)badge.textContent='API not connected';badge?.classList.remove('active');badge?.classList.add('waiting');return}if(status)status.textContent='Detecting country and matching registered rescue operators…';try{const data=await api(`/api/rescue-location?lat=${encodeURIComponent(lat)}&lng=${encodeURIComponent(lng)}`);rescueCountryCode=data.countryCode||'';rescueOperatorCount=Number(data.operatorCount||0);if(status)status.textContent=`Country: ${data.countryName||rescueCountryCode||'Unknown'} · ${rescueOperatorCount} configured operator${rescueOperatorCount===1?'':'s'} matched.`;if(badge){badge.textContent=rescueOperatorCount?`${rescueOperatorCount} operator${rescueOperatorCount===1?'':'s'} matched`:'No operator configured';badge.classList.toggle('active',!!rescueOperatorCount);badge.classList.toggle('waiting',!rescueOperatorCount)}}catch(e){if(status)status.textContent='Country detection is unavailable. The rescue report can still be submitted with coordinates.';if(badge)badge.textContent='Routing unavailable';}}
