function loadLeafletForRescue(){if(window.L)return Promise.resolve(true);return new Promise(resolve=>{let settled=false;const done=v=>{if(settled)return;settled=true;resolve(v)};const cssId='pp-leaflet-css';if(!document.getElementById(cssId)){const link=document.createElement('link');link.id=cssId;link.rel='stylesheet';link.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(link)}const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.async=true;script.crossOrigin='anonymous';script.onload=()=>done(!!window.L);script.onerror=()=>done(false);document.head.appendChild(script);setTimeout(()=>done(!!window.L),6500)})}
function initRescueMap(){const mapEl=el('#rescueMap');if(!mapEl)return;if(!window.L){const fallback=el('#rescueMapFallback');if(fallback)fallback.hidden=false;renderRescueList();return}const fallback=el('#rescueMapFallback');if(fallback)fallback.hidden=true;if(rescueMap)return;rescueMap=L.map(mapEl,{scrollWheelZoom:true,zoomControl:true}).setView(RESCUE_DEFAULT,RESCUE_ZOOM);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(rescueMap);rescueMap.on('click',e=>setRescueCoords(e.latlng.lat,e.latlng.lng,true));renderRescueMarkers();setTimeout(()=>rescueMap.invalidateSize(),150);}
async function syncRescuesFromApi(){if(!API_BASE)return;try{const data=await api('/api/rescues');if(Array.isArray(data.rescues)){const local=loadLocalRescues();const map=new Map([...local,...data.rescues].map(r=>[r.id||`${r.createdAt}|${r.lat}|${r.lng}`,{...r}]));saveLocalRescues([...map.values()].slice(-100));renderRescueMarkers();renderRescueList()}}catch(e){/* local rescue mode remains available */}}
function validRescueCoords(lat,lng){return Number.isFinite(lat)&&Number.isFinite(lng)&&lat>=-90&&lat<=90&&lng>=-180&&lng<=180}
async function imageToDataUrl(file){const img=await new Promise((resolve,reject)=>{const u=URL.createObjectURL(file);const i=new Image();i.onload=()=>{URL.revokeObjectURL(u);resolve(i)};i.onerror=reject;i.src=u});const max=1400,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);let q=.78,data=canvas.toDataURL('image/jpeg',q);while(data.length>1250000&&q>.48){q-=.06;data=canvas.toDataURL('image/jpeg',q)}return data}
