function revokeRescueMediaUrl(){if(rescueMediaUrl){URL.revokeObjectURL(rescueMediaUrl);rescueMediaUrl=''}}
function clearRescueMedia(){revokeRescueMediaUrl();rescueMediaFile=null;rescueMediaType='';const input=el('#rescueMediaInput'),preview=el('#rescueMediaPreview'),badge=el('#rescueMediaState');if(input)input.value='';if(preview){preview.innerHTML='';preview.hidden=true}if(badge){badge.textContent='No media';badge.classList.remove('ready','video')}}
function showRescueMedia(file,type){if(!file)return;revokeRescueMediaUrl();rescueMediaFile=file;rescueMediaType=type;rescueMediaUrl=URL.createObjectURL(file);const preview=el('#rescueMediaPreview'),badge=el('#rescueMediaState');if(!preview)return;preview.hidden=false;preview.innerHTML=type==='photo'?`<img src="${rescueMediaUrl}" alt="Selected rescue photo"><div class="media-caption">Photo ready · ${Math.round(file.size/1024)} KB</div>`:`<video src="${rescueMediaUrl}" controls playsinline></video><div class="media-caption">Video ready · ${Math.round(file.size/1024)} KB</div>`;if(badge){badge.textContent=type==='video'?'Video ready':'Photo ready';badge.classList.add('ready');badge.classList.toggle('video',type==='video')}}
function stopRescueCamera(){if(rescueVideoRecorder&&rescueVideoRecorder.state==='recording')rescueVideoRecorder.stop();if(rescueCameraStream){rescueCameraStream.getTracks().forEach(t=>t.stop());rescueCameraStream=null}const box=el('#rescueLiveCamera'),preview=el('#rescueCameraPreview'),close=el('#rescueCameraClose');if(box)box.hidden=true;if(preview)preview.srcObject=null;if(close)close.hidden=true;el('#rescueCameraOpen')?.removeAttribute('hidden')}
async function openRescueCamera(){if(!navigator.mediaDevices?.getUserMedia){toast('Live camera is not supported by this browser');return}try{rescueCameraStream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});const video=el('#rescueCameraPreview');if(video){video.srcObject=rescueCameraStream;await video.play().catch(()=>{})}el('#rescueLiveCamera').hidden=false;el('#rescueCameraOpen').hidden=true;el('#rescueCameraClose').hidden=false;toast('Live camera is on')}catch(e){toast('Camera permission was denied or unavailable')}}
function takeRescuePhoto(){const video=el('#rescueCameraPreview');if(!video||!video.videoWidth)return toast('Wait for the camera preview to start');const canvas=document.createElement('canvas');const max=1400,scale=Math.min(1,max/Math.max(video.videoWidth,video.videoHeight));canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(blob)showRescueMedia(new File([blob],'rescue-camera.jpg',{type:'image/jpeg'}),'photo')},'image/jpeg',.78);toast('Photo captured')}
function startRescueVideo(){if(!rescueCameraStream||!window.MediaRecorder){toast('Video recording is not supported');return}rescueVideoChunks=[];const options=MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus')?{mimeType:'video/webm;codecs=vp8,opus',videoBitsPerSecond:160000}:{videoBitsPerSecond:160000};rescueVideoRecorder=new MediaRecorder(rescueCameraStream,options);rescueVideoRecorder.ondataavailable=e=>{if(e.data?.size)rescueVideoChunks.push(e.data)};rescueVideoRecorder.onstop=()=>{const blob=new Blob(rescueVideoChunks,{type:rescueVideoRecorder.mimeType||'video/webm'});if(blob.size>950000){toast('Video is too large; please record a shorter clip');return}showRescueMedia(new File([blob],'rescue-camera.webm',{type:'video/webm'}),'video');toast('Video recording ready')};rescueVideoRecorder.start(500);el('#rescueRecordVideo').disabled=true;el('#rescueStopVideo').disabled=false;let left=15;const timer=setInterval(()=>{left--;el('#rescueRecordVideo').textContent=`Recording ${left}s`;if(left<=0){clearInterval(timer);stopRescueVideo()}},1000)}
