async function submitRescueRequest(e){e.preventDefault();const fd=new FormData(e.target);const lat=Number(fd.get('lat')),lng=Number(fd.get('lng'));const request={id:cryptoSafeId(),animal:String(fd.get('animal')||'cat'),urgency:String(fd.get('urgency')||'normal'),description:String(fd.get('description')||'').trim(),name:String(fd.get('name')||'').trim(),phone:String(fd.get('phone')||'').trim(),place:String(fd.get('place')||'').trim(),lat,lng,status:'open',createdAt:new Date().toISOString(),date:new Date().toLocaleDateString('en-BD',{year:'numeric',month:'short',day:'numeric'})};if(!validRescueCoords(lat,lng)){toast('Choose a map location or enter valid latitude and longitude');return}if(!['cat','dog','bird'].includes(request.animal)){toast('Choose cat, dog or bird');return}if(request.description.length<5){toast('Please describe what help the animal needs');return}if(request.phone&&!validBDPhone(request.phone)){toast('Enter a valid Bangladesh phone number or leave phone blank');return}let media=null;try{media=await mediaPayload();if(rescueMediaFile&&!media){toast('Media is too large. Choose a smaller photo or shorter video');return}}catch(e){toast('Could not prepare the attached media');return}let remote=false;let response=null;try{if(API_BASE){response=await api('/api/rescues',{method:'POST',body:JSON.stringify({...request,media})});if(response.rescue){Object.assign(request,response.rescue);request.hasMedia=!!response.rescue.hasMedia;request.mediaType=response.rescue.mediaType||rescueMediaType;request.countryCode=response.rescue.countryCode;request.countryName=response.rescue.countryName;remote=true;const n=response.notifications||{};const status=el('#rescueFormStatus');if(status)status.textContent=n.providerConfigured?(n.sent?`Country: ${n.countryName||request.countryName||'detected'} · ${n.sent} operator SMS alert${n.sent===1?'':'s'} sent.`:`No SMS was sent. ${n.matchedOperators||0} operator${n.matchedOperators===1?'':'s'} matched, but delivery was not available.`):`Country: ${n.countryName||request.countryName||'detected'} · operator routing is ready, but SMS provider is not configured yet.`}}}catch(e){console.warn('rescue API fallback',e)}const items=loadLocalRescues();items.push(request);saveLocalRescues(items);renderRescueMarkers();renderRescueList();if(rescueMap)rescueMap.setView([lat,lng],Math.max(rescueMap.getZoom(),15));const st=el('#rescueFormStatus');if(st&&!remote)st.textContent='Help request saved on this browser. Connect the rescue API to detect country, notify operators by SMS, and share the rescue marker across devices.';toast(remote?'Rescue help request sent':'Rescue marker saved on this device');e.target.reset();clearRescueMedia();setRescueCoords(lat,lng,false)}
function initRescueModule(){const form=el('#rescueForm');if(form)form.onsubmit=submitRescueRequest;el('#rescueLocate')?.addEventListener('click',()=>{if(!navigator.geolocation){toast('Location is not available in this browser');return}navigator.geolocation.getCurrentPosition(p=>setRescueCoords(p.coords.latitude,p.coords.longitude,true),()=>toast('Could not access your location. Click the map instead.'),{enableHighAccuracy:true,timeout:10000,maximumAge:60000})});el('#rescueResetMap')?.addEventListener('click',()=>{if(rescueMap){rescueMap.setView(RESCUE_DEFAULT,RESCUE_ZOOM);setTimeout(()=>rescueMap.invalidateSize(),100)}const h=el('#rescueMapHint');if(h)h.textContent='Click the map to place a marker, or use your device location.';const cs=el('#rescueCountryStatus');if(cs)cs.textContent='Choose a map location to detect the country and match configured rescue operators.'});el('#refreshRescues')?.addEventListener('click',()=>{syncRescuesFromApi();renderRescueMarkers();renderRescueList();toast('Rescue markers refreshed')});el('#rescueMediaInput')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(f.type.startsWith('image/')){if(f.size>5000000)return toast('Choose an image under 5 MB');showRescueMedia(f,'photo')}else if(f.type.startsWith('video/')){if(f.size>950000)return toast('Choose a short video under 950 KB, or record one with the camera');showRescueMedia(f,'video')}else toast('Please choose a photo or video')});el('#rescueCameraOpen')?.addEventListener('click',openRescueCamera);el('#rescueCameraClose')?.addEventListener('click',stopRescueCamera);el('#rescueTakePhoto')?.addEventListener('click',takeRescuePhoto);el('#rescueRecordVideo')?.addEventListener('click',startRescueVideo);el('#rescueStopVideo')?.addEventListener('click',stopRescueVideo);initRescueMap();loadLeafletForRescue().then(ok=>{if(ok){initRescueMap();const map=el('#rescueMap');if(map)map.setAttribute('data-map-ready','true')}else{const h=el('#rescueMapHint');if(h)h.textContent='Map library is unavailable right now. Enter latitude and longitude manually to report a rescue.'}});syncRescuesFromApi();if(API_BASE){window.__rescuePoll=window.setInterval(()=>{if(document.visibilityState==='visible')syncRescuesFromApi()},30000)}updateVoiceSendLabel()}
function toast(msg){const t=el('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),3000)}
